// Generate an independent iOS product from the maintained native sources.
// Edit native/ios; this product copy is regenerated by every sync.
import { cp, mkdir, readFile, writeFile, symlink, lstat } from 'node:fs/promises';
import { dirname, resolve, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
const nativeDir = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const products = {
  'record-keeper': {
    surface: 'rk', name: 'Record Keeper', bundle: 'com.johnnyoutlaw.recordkeeper',
    url: 'https://recordkeeper.stream', scheme: 'https', hostname: 'app.recordkeeper.stream',
    logo: '../public/brand/rk/icon-512.png',
  },
  'suffering-jukebox': {
    surface: 'sj', name: 'Suffering Jukebox', bundle: 'com.johnnyoutlaw.sufferingjukebox.ios',
    authScheme: 'com.johnnyoutlaw.sufferingjukebox',
    url: 'https://www.sufferingjukebox.stream', scheme: 'capacitor', hostname: 'www.sufferingjukebox.stream',
    logo: 'assets/suffering-jukebox-mark.png',
  },
};
const [, , slug, action = 'sync'] = process.argv;
if (!Object.hasOwn(products, slug)) throw new Error('Use record-keeper or suffering-jukebox');
if (!['sync', 'open'].includes(action)) throw new Error('Use sync or open');
const { surface, name, bundle, authScheme = bundle, url, scheme, hostname, logo } = products[slug];
const product = resolve(nativeDir, 'products', slug);
await mkdir(product, { recursive: true });
await cp(resolve(nativeDir, 'ios'), resolve(product, 'ios'), {
  recursive: true,
  filter: path => !relative(resolve(nativeDir, 'ios'), path).split(sep).some(p =>
    ['Pods', 'public', 'xcuserdata', 'DerivedData', 'build', 'capacitor-cordova-ios-plugins'].includes(p)),
});
try { await lstat(resolve(product, 'node_modules')); } catch (error) {
  if (error.code !== 'ENOENT') throw error;
  await symlink(resolve(nativeDir, 'node_modules'), resolve(product, 'node_modules'), 'junction');
}
const config = JSON.parse(await readFile(resolve(nativeDir, 'capacitor.config.json'), 'utf8'));
config.appId = bundle;
config.appName = name;
config.server.iosScheme = scheme;
config.server.hostname = hostname;
if (surface === 'rk') config.server.allowNavigation.unshift('recordkeeper.stream', '*.recordkeeper.stream');
await writeFile(resolve(product, 'capacitor.config.json'), JSON.stringify(config, null, 2) + '\n');
await writeFile(resolve(product, 'package.json'), JSON.stringify({ name: `${slug}-ios`, version: '1.0.0', private: true }, null, 2) + '\n');
async function transform(path, update) {
  const target = resolve(product, path);
  await writeFile(target, update(await readFile(target, 'utf8')));
}
await transform('ios/App/App.xcodeproj/project.pbxproj', text => text
  .replaceAll('com.johnnyoutlaw.sufferingjukebox', bundle)
  .replace(/CURRENT_PROJECT_VERSION = \d+;/g, 'CURRENT_PROJECT_VERSION = 1;')
  .replace(/MARKETING_VERSION = [\d.]+;/g, 'MARKETING_VERSION = 1.0.0;'));
await transform('ios/App/App/Info.plist', text => text.replaceAll('Listening Party', name).replaceAll('com.johnnyoutlaw.listeningparty', authScheme));
await transform('ios/App/App/App.entitlements', text => text.replaceAll('com.johnnyoutlaw.sufferingjukebox', bundle));
await transform('ios/App/App/CarPlay/SJCarPlaySceneDelegate.swift', text => text.replaceAll('Listening Party', name).replaceAll('listeningparty.stream', new URL(url).hostname));
await transform('ios/App/App/Audio/SJStreamLibrary.swift', text => text.replaceAll('https://listeningparty.stream', url));
await transform('ios/App/App/Audio/SJDownloader.swift', text => text.replaceAll('com.johnnyoutlaw.sufferingjukebox.downloads', bundle + '.downloads'));
const assets = resolve(product, 'ios/App/App/Assets.xcassets');
execFileSync('xcrun', ['swift', resolve(nativeDir, 'scripts/render-record-keeper-assets.swift'),
  resolve(nativeDir, logo), assets], { stdio: 'inherit' });
execFileSync(process.execPath, [resolve(nativeDir, 'scripts/build-web.mjs')], {
  cwd: product, stdio: 'inherit', env: { ...process.env, SJ_NATIVE_SURFACE: surface, SJ_NATIVE_APP_DIR: product },
});
const cap = resolve(nativeDir, 'node_modules/@capacitor/cli/bin/capacitor');
execFileSync(process.execPath, [cap, 'sync', 'ios'], {
  cwd: product, stdio: 'inherit', env: { ...process.env, LANG: 'en_US.UTF-8', LC_ALL: 'en_US.UTF-8' },
});
if (action === 'open') execFileSync(process.execPath, [cap, 'open', 'ios'], { cwd: product, stdio: 'inherit' });
console.log(`${name} iOS workspace: ${product}/ios/App/App.xcworkspace`);
